old="function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}"
new="function toast(message,undo=null){const el=document.querySelector('#toast');el.replaceChildren(document.createTextNode(message));if(undo){const b=document.createElement('button');b.type='button';b.className='toast-undo';b.textContent='Deshacer';b.onclick=()=>{undo();el.classList.remove('visible');};el.append(b);}el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5200);}"
one(old,new,'toast undo')

