old="function showModal(title,body,onSubmit){modal.innerHTML=`<div class=\"modal-heading\"><h2>${title}</h2>${btn(icon('X'),'close','aria-label=\"Cerrar\"','icon-button')}</div>${body}`;if(!modal.open)modal.showModal();paintIcons();const f=modal.querySelector('form');if(f)f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('[type=\"submit\"]');if(submit)submit.disabled=true;try{await onSubmit(new FormData(f));}catch(error){toast('No se pudo guardar: '+error.message);}finally{if(submit)submit.disabled=false;}};}"
new="function showModal(title,body,onSubmit){modal.dataset.dirty='false';modal.innerHTML=`<div class=\"modal-heading\"><h2>${title}</h2>${btn(icon('X'),'close','aria-label=\"Cerrar\"','icon-button')}</div>${body}`;if(!modal.open)modal.showModal();paintIcons();const f=modal.querySelector('form');if(f){f.addEventListener('input',()=>modal.dataset.dirty='true');f.addEventListener('change',()=>modal.dataset.dirty='true');f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('[type=\"submit\"]');if(submit)submit.disabled=true;try{await onSubmit(new FormData(f));modal.dataset.dirty='false';}catch(error){toast('No se pudo guardar: '+error.message);}finally{if(submit)submit.disabled=false;}};}modal.oncancel=e=>{if(modal.dataset.dirty==='true'){e.preventDefault();if(confirm('Tenés cambios sin guardar. ¿Descartarlos?')){modal.dataset.dirty='false';modal.close();}}};}\nfunction closeModalSafely(){if(modal.dataset.dirty==='true'&&!confirm('Tenés cambios sin guardar. ¿Descartarlos?'))return false;modal.dataset.dirty='false';modal.close();return true;}"
one(old,new,'dirty forms')

